mapper.select:
SELECT station_code stationCode,temp10,temp90,prcp95,prcp99,humidity5,
temp_samples tempSamples,prcp_samples prcpSamples,humidity_samples humiditySamples
FROM station_threshold WHERE station_code=#{station}

mapper.sql:
AND region_level=#{level} AND metric=#{metric}
AND country=#{country}
AND province=#{province}
AND city=#{city}
AND district=#{district}
